const html = String($input.first().json.body ?? $input.first().json.data ?? $input.first().json);
const baseUrl = 'https://zakon.rada.gov.ua';
const limit = Number($env.JUR_RADA_SYNC_LIMIT || 1);
const workspaceId = $env.JUR_KB_WORKSPACE_ID || '00000000-0000-0000-0000-000000000101';
const userId = $env.JUR_KB_USER_ID || '00000000-0000-0000-0000-000000000001';
function stripTags(value) {
  return String(value || '').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
}
function decodeHtml(value) {
  return String(value || '').replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
}
function absoluteRadaUrl(href) {
  const value = String(href || '').trim();
  if (value.startsWith('https://zakon.rada.gov.ua')) return value.replace('/go/', '/laws/show/');
  if (value.startsWith('http://zakon.rada.gov.ua')) return value.replace('http://', 'https://').replace('/go/', '/laws/show/');
  if (value.startsWith('/')) return `${baseUrl}${value}`.replace('/go/', '/laws/show/');
  return `${baseUrl}/${value.replace(/^\/+/, '')}`.replace('/go/', '/laws/show/');
}
function sourceType(title) {
  const text = title.toLowerCase();
  if (text.includes('конституц')) return 'constitution';
  if (text.includes('кодекс')) return 'code';
  if (text.includes('постанова')) return 'cabinet_resolution';
  if (text.includes('наказ')) return 'executive_regulation';
  if (text.includes('роз\'яснення')) return 'state_explanation';
  return 'law';
}
const rows = [];
const seen = new Set();
const anchorRe = /<a[^>]+href=["']([^"']*(?:\/laws\/show\/|\/go\/)[^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
let match;
while ((match = anchorRe.exec(html)) && rows.length < limit) {
  const href = match[1];
  const sourceUrl = absoluteRadaUrl(href);
  if (seen.has(sourceUrl)) continue;
  seen.add(sourceUrl);
  const sourceName = decodeHtml(stripTags(match[2])).replace(/\s+/g, ' ').trim();
  if (!sourceName) continue;
  const documentNumber = decodeURIComponent(sourceUrl.split('/').pop().split(/[?#]/)[0]);
  rows.push({
    workspace_id: workspaceId,
    user_id: userId,
    source_name: sourceName,
    source_type: sourceType(sourceName),
    source_url: sourceUrl,
    document_number: documentNumber,
    validity_status: 'current',
    jurisdiction: 'Ukraine',
    last_checked_at: new Date().toISOString()
  });
}
return rows.map(row => ({ json: row }));

const item = $('Split Rada Documents').first().json;
const html = String($input.first().json.body ?? $input.first().json.data ?? $input.first().json);
function stripTags(value) {
  return String(value || '').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
}
function decodeHtml(value) {
  return String(value || '').replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
}
const fullText = decodeHtml(stripTags(html)).replace(/\s+/g, ' ').trim();
const officialNumberMatch = fullText.match(/№\s*([0-9]+-[A-ZА-ЯІЇЄҐXVI]+)\b/u);
const officialDocumentNumber = officialNumberMatch ? officialNumberMatch[1] : item.document_number;
const sample = fullText.slice(0, 1500);
const ollamaModel = $env.JUR_OLLAMA_MODEL || 'qwen3:8b';
return [{
  json: {
    ...item,
    document_number: officialDocumentNumber,
    full_text: fullText,
    file_path: `official_html/rada/${String(item.document_number || Date.now()).replace(/[^A-Za-z0-9_.-]+/g, '_')}.html`,
    ollama_request: {
      model: ollamaModel,
      stream: false,
      messages: [
        { role: 'system', content: 'Ти юридичний класифікатор. Поверни тільки JSON без Markdown.' },
        { role: 'user', content: `Офіційний акт України з zakon.rada.gov.ua. Не змінюй офіційні реквізити. Дай JSON: {"summary":"короткий зміст українською", "topic_tags":["tag1"], "source_type":"law|code|constitution|cabinet_resolution|executive_regulation|state_explanation|supreme_court_position"}. Назва: ${item.source_name}\n\nТекст:\n${sample}` }
      ]
    }
  }
}];

const source = $('Prepare Ollama Request').first().json;
const response = $input.first().json;
function parseJsonObject(value) {
  const text = String(value || '').replace(/```json|```/g, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return {};
  try { return JSON.parse(text.slice(start, end + 1)); } catch (error) { return {}; }
}
const enrichment = parseJsonObject(response?.message?.content || response?.response || '');
const tags = Array.isArray(enrichment.topic_tags) && enrichment.topic_tags.length ? enrichment.topic_tags : ['official-source', 'rada'];
return [{
  json: {
    workspace_id: source.workspace_id,
    user_id: source.user_id,
    source_name: source.source_name,
    source_type: enrichment.source_type || source.source_type,
    source_url: source.source_url,
    document_number: source.document_number,
    validity_status: source.validity_status,
    jurisdiction: source.jurisdiction,
    last_checked_at: source.last_checked_at,
    topic_tags: tags,
    summary: enrichment.summary || null,
    full_text: source.full_text,
    file_path: source.file_path
  }
}];
